    .bio-card-container{ margin: 60px 36px; } .bio-card{ display:flex; gap:18px; align-items:center; padding:18px; border-radius:10px; box-shadow:0 4px 14px rgba(2,6,23,0.06); background:var(--card-bg); }
    .bio-photo{ width:140px; height:180px; object-fit:cover; border-radius:6px; } .bio-main{ flex:1 1 auto; display:flex; flex-direction:column; gap:6px; }
    .bio-stats{ display:flex; gap:12px; align-items:center; margin-top:8px; } .stat-pill{ background:#eef3fb; padding:6px 10px; border-radius:8px; font-weight:700; color:var(--accent); }
    .tabs{ margin: 18px 36px; } .tab-list{ display:flex; gap:8px; } .tab-list button{ padding:10px 14px; border-radius:8px; border:1px solid #e6eef7; background:#fff; cursor:pointer; }
    .tab-list button[aria-selected="true"]{ background:#0b5fff; color:#fff; border-color:#0b5fff; } .tab-panel{ margin-top:12px; padding:18px; border-radius:8px; background:#fff; box-shadow:0 2px 8px rgba(0,0,0,0.04); }
    .article-list{ list-style:none; padding:0; margin:0; display:flex; flex-direction:column; gap:10px; } .article-list a{ color:var(--accent); font-weight:700; text-decoration:none; }



