    (function(){ const bioTab=document.getElementById('tab-bio'), artTab=document.getElementById('tab-articles'), bioPanel=document.getElementById('panel-bio'), artPanel=document.getElementById('panel-articles'); function select(t){ if(t==='bio'){bioTab.setAttribute('aria-selected','true'); artTab.setAttribute('aria-selected','false'); bioPanel.hidden=false; artPanel.hidden=true;} else{bioTab.setAttribute('aria-selected','false'); artTab.setAttribute('aria-selected','true'); bioPanel.hidden=true; artPanel.hidden=false;} } bioTab.addEventListener('click',()=>select('bio')); artTab.addEventListener('click',()=>select('articles')); })();
    (function(){ const athleteNames=['Larry Davis','Larry','Davis']; const candidates=['../articles_index.json','/articles_index.json','articles_index.json']; function tryLoad(i){ if(i>=candidates.length){ document.getElementById('article-list').innerHTML='<li>No articles found.</li>'; return;} fetch(candidates[i]).then(r=>{ if(!r.ok) throw new Error('HTTP '+r.status); return r.json(); }).then(list=>{ const matches=list.filter(a=> a.mentions && a.mentions.some(m=> athleteNames.some(n=> m.toLowerCase().includes(n.toLowerCase()) || n.toLowerCase().includes(m.toLowerCase())))); const ul=document.getElementById('article-list'); ul.innerHTML=''; if(matches.length===0){ ul.innerHTML='<li>No articles found.</li>'; return; } matches.forEach(a=>{ const li=document.createElement('li'); const link=document.createElement('a'); link.href=a.url; link.textContent=a.title+' — '+a.date; li.appendChild(link); ul.appendChild(li); }); }).catch(()=>tryLoad(i+1)); } tryLoad(0); })();

